/** Foreground-only local HTTPS. A TV-scanned certificate pin authenticates peer transfers. */
final class VelaConnect implements AutoCloseable {
    interface Commands {JSONObject state(int page)throws Exception;void action(JSONObject request)throws Exception;}
    private final Context context;private final Commands commands;private final boolean mobile;private final String profile,token;private final long expires;
    volatile String handshakeFailure="";private SSLServerSocket socket;private volatile Socket current;private Thread thread;private volatile boolean closed;private final String address,fingerprint;private final String certAlias;
    static String random(){byte[] b=new byte[24];new SecureRandom().nextBytes(b);return Base64.encodeToString(b,Base64.NO_WRAP|Base64.URL_SAFE|Base64.NO_PADDING);}
    static SharedPreferences privatePrefs(Context c){return c.getSharedPreferences("vela-connections-private",0);}
    static synchronized void secret(Context c,String key,String value)throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);String alias=c.getPackageName()+".connections.data";if(!store.containsAlias(alias)){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,(Key)store.getKey(alias,null));String encoded=Base64.encodeToString(cipher.getIV(),2)+"."+Base64.encodeToString(cipher.doFinal(value.getBytes(StandardCharsets.UTF_8)),2);if(!privatePrefs(c).edit().putString(key,encoded).commit())throw new IOException("Private setting unavailable");}
    static synchronized String secret(Context c,String key)throws Exception{String v=privatePrefs(c).getString(key,"");if(v.isEmpty())return "";String[] b=v.split("\\.");if(b.length!=2)throw new IOException("Private setting unavailable");KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,(Key)store.getKey(c.getPackageName()+".connections.data",null),new GCMParameterSpec(128,Base64.decode(b[0],2)));return new String(cipher.doFinal(Base64.decode(b[1],2)),StandardCharsets.UTF_8);}
    static String ip()throws Exception{for(NetworkInterface n:Collections.list(NetworkInterface.getNetworkInterfaces()))if(n.isUp()&&!n.isLoopback())for(InetAddress a:Collections.list(n.getInetAddresses()))if(a instanceof Inet4Address&&a.isSiteLocalAddress())return a.getHostAddress();throw new IOException("Connect this television to your local network");}
    VelaConnect(Context c,Commands commands,boolean mobile)throws Exception{
        context=c.getApplicationContext();this.commands=commands;this.mobile=mobile;profile=VelaWorkspace.active(c);address=ip();expires=mobile?android.os.SystemClock.elapsedRealtime()+10*60_000:Long.MAX_VALUE;String stable=mobile?random():secret(c,"host-token-"+profile);if(stable.isEmpty()){stable=random();secret(c,"host-token-"+profile,stable);}token=stable;certAlias=c.getPackageName()+".connections."+(mobile?random():"host-ec-tls1");
        KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias(certAlias)){KeyPairGenerator g=KeyPairGenerator.getInstance("EC","AndroidKeyStore");g.initialize(new KeyGenParameterSpec.Builder(certAlias,KeyProperties.PURPOSE_SIGN|KeyProperties.PURPOSE_VERIFY).setAlgorithmParameterSpec(new ECGenParameterSpec("secp256r1")).setDigests(KeyProperties.DIGEST_NONE,KeyProperties.DIGEST_SHA256,KeyProperties.DIGEST_SHA384,KeyProperties.DIGEST_SHA512).setCertificateSubject(new X500Principal("CN=Vela local")).setCertificateSerialNumber(new BigInteger(120,new SecureRandom())).setCertificateNotBefore(new Date(System.currentTimeMillis()-86400_000)).setCertificateNotAfter(new Date(System.currentTimeMillis()+3650L*86400_000)).build());g.generateKeyPair();}
        fingerprint=hex(MessageDigest.getInstance("SHA-256").digest(store.getCertificate(certAlias).getEncoded()));
        // TLS hashes its transcript before calling the keystore: DIGEST_NONE authorizes that prehashed signature.
        // Restrict selection to this session's alias; the Android keystore may hold other app keys.
        PrivateKey sessionKey=(PrivateKey)store.getKey(certAlias,null);X509Certificate[] chain=new X509Certificate[]{(X509Certificate)store.getCertificate(certAlias)};X509ExtendedKeyManager manager=new X509ExtendedKeyManager(){public String chooseEngineClientAlias(String[] t,java.security.Principal[] p,SSLEngine e){return null;}public String chooseEngineServerAlias(String t,java.security.Principal[] p,SSLEngine e){return t.startsWith("EC")?certAlias:null;}public String[] getClientAliases(String t,java.security.Principal[] p){return null;}public String chooseClientAlias(String[] t,java.security.Principal[] p,Socket s){return null;}public String[] getServerAliases(String t,java.security.Principal[] p){return t.startsWith("EC")?new String[]{certAlias}:null;}public String chooseServerAlias(String t,java.security.Principal[] p,Socket s){return t.startsWith("EC")?certAlias:null;}public X509Certificate[] getCertificateChain(String alias){return certAlias.equals(alias)?chain:null;}public PrivateKey getPrivateKey(String alias){return certAlias.equals(alias)?sessionKey:null;}};
        SSLContext tls=SSLContext.getInstance("TLS");tls.init(new KeyManager[]{manager},null,new SecureRandom());socket=(SSLServerSocket)tls.getServerSocketFactory().createServerSocket();socket.setReuseAddress(true);int port=mobile?0:privatePrefs(c).getInt("host-port",0);socket.bind(new InetSocketAddress(address,port));socket.setSoTimeout(1000);socket.setEnabledProtocols(new String[]{"TLSv1.2"});if(!mobile)privatePrefs(c).edit().putInt("host-port",socket.getLocalPort()).commit();thread=new Thread(this::serve,"vela-local-https");thread.setPriority(Thread.MIN_PRIORITY);thread.start();
    }
    String url(){return "https://"+address+":"+socket.getLocalPort()+"/"+(mobile?"m/":"s/")+token+(mobile?"":"#"+fingerprint);}
    String certificate(){return fingerprint;}
    private void serve(){while(!closed&&android.os.SystemClock.elapsedRealtime()<expires){try{Socket s=socket.accept();current=s;try{if(!s.getInetAddress().isSiteLocalAddress()&&!s.getInetAddress().isLoopbackAddress())continue;s.setSoTimeout(6000);try{((SSLSocket)s).startHandshake();}catch(SSLException handshake){handshakeFailure=handshake.toString();throw handshake;}handle(s);}finally{s.close();current=null;}}catch(SocketTimeoutException tick){}catch(Exception ignored){/* Never log requests, credentials, endpoints or pairing tokens. */}}close();}
    static String line(InputStream in,int max)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();for(int n;(n=in.read())!=-1;){if(n==10)return b.toString("US-ASCII").replace("\r","");if(b.size()>=max)throw new IOException("Header too large");b.write(n);}throw new EOFException();}
    private void handle(Socket s)throws Exception{
        InputStream in=s.getInputStream();String[] request=line(in,2048).split(" ");if(request.length!=3)return;Map<String,String> headers=new HashMap<>();for(int i=0;i<24;i++){String h=line(in,4096);if(h.isEmpty())break;int k=h.indexOf(':');if(k<1)return;String key=h.substring(0,k).toLowerCase(Locale.ROOT);if(headers.put(key,h.substring(k+1).trim())!=null)return;if(i==23)return;}
        String host=address+":"+socket.getLocalPort(),path=request[1];if(!host.equals(headers.get("host"))||headers.containsKey("transfer-encoding"))return;String origin=headers.get("origin");if(origin!=null&&!origin.equals("https://"+host))return;if(closed||!profile.equals(VelaWorkspace.active(context)))return;
        if(!mobile){if(request[0].equals("GET")&&path.equals("/s/"+token)){JSONObject copy; synchronized(VelaWorkspace.class){copy=VelaWorkspace.snapshot(context);}reply(s,"application/json",copy.toString().getBytes(StandardCharsets.UTF_8));}return;}
        String base="/m/"+token;if(request[0].equals("GET")&&path.equals(base)){reply(s,"text/html; charset=utf-8",page(base).getBytes(StandardCharsets.UTF_8));return;}
        if(request[0].equals("GET")&&path.startsWith(base+"/state?p=")){int p=Integer.parseInt(path.substring((base+"/state?p=").length()));if(p<0||p>1000)return;reply(s,"application/json",commands.state(p).toString().getBytes(StandardCharsets.UTF_8));return;}
        if(request[0].equals("POST")&&path.equals(base+"/action")&&"application/json".equals(headers.get("content-type"))){int n=Integer.parseInt(headers.getOrDefault("content-length","0"));if(n<2||n>32*1024)return;byte[] body=new byte[n];int at=0;while(at<n){int got=in.read(body,at,n-at);if(got<0)throw new EOFException();at+=got;}JSONObject answer=new JSONObject();try{JSONObject action=new JSONObject(new String(body,StandardCharsets.UTF_8));if(action.optString("op").equals("source")){commands.action(action);}else synchronized(VelaWorkspace.class){if(!profile.equals(VelaWorkspace.active(context)))return;commands.action(action);}answer.put("ok",true);}catch(Exception bad){answer.put("ok",false).put("message",L10n.text("Could not save the change. Check the fields and connection."));}Arrays.fill(body,(byte)0);reply(s,"application/json",answer.toString().getBytes(StandardCharsets.UTF_8));}
    }
    private static void reply(Socket s,String type,byte[] body)throws IOException{if(body.length>VelaWorkspace.MAX_BYTES)throw new IOException("Response too large");OutputStream out=s.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: "+type+"\r\nContent-Length: "+body.length+"\r\nCache-Control: no-store\r\nReferrer-Policy: no-referrer\r\nX-Content-Type-Options: nosniff\r\nContent-Security-Policy: default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(body);out.flush();}
    static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
    static JSONObject receive(String link)throws Exception{URI uri=new URI(link);String pin=uri.getFragment();if(!"https".equals(uri.getScheme())||uri.getUserInfo()!=null||uri.getQuery()!=null||pin==null||!pin.matches("[a-f0-9]{64}")||uri.getPort()<1||uri.getPort()>65535||!uri.getRawPath().matches("/s/[A-Za-z0-9_-]{32}"))throw new IOException("Invalid pairing link");InetAddress ip=InetAddress.getByName(uri.getHost());if(!ip.isSiteLocalAddress()&&!ip.isLoopbackAddress())throw new IOException("Local network only");X509TrustManager trust=new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] a,String t)throws java.security.cert.CertificateException{throw new java.security.cert.CertificateException();}public void checkServerTrusted(X509Certificate[] a,String t)throws java.security.cert.CertificateException{try{if(a.length<1||!pin.equals(hex(MessageDigest.getInstance("SHA-256").digest(a[0].getEncoded()))))throw new java.security.cert.CertificateException("Pairing certificate mismatch");a[0].checkValidity();}catch(java.security.cert.CertificateException e){throw e;}catch(Exception e){throw new java.security.cert.CertificateException(e);}}};SSLContext tls=SSLContext.getInstance("TLS");tls.init(null,new TrustManager[]{trust},new SecureRandom());URL url=new URL("https://"+ip.getHostAddress()+":"+uri.getPort()+uri.getRawPath());HttpsURLConnection c=(HttpsURLConnection)url.openConnection();c.setSSLSocketFactory(tls.getSocketFactory());c.setHostnameVerifier((h,s)->h.equals(ip.getHostAddress()));c.setConnectTimeout(5000);c.setReadTimeout(6000);c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)throw new IOException("Peer unavailable");try(InputStream in=c.getInputStream()){return VelaWorkspace.read(in);}}finally{c.disconnect();}}
    public synchronized void close(){if(closed)return;closed=true;if(thread!=null&&thread!=Thread.currentThread())thread.interrupt();try{if(current!=null)current.close();if(socket!=null)socket.close();}catch(IOException ignored){}if(mobile)try{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);store.deleteEntry(certAlias);}catch(Exception ignored){}}
    private String page(String base)throws IOException{try(InputStream in=context.getAssets().open("connect.html")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];for(int n;(n=in.read(b))!=-1;){if(out.size()+n>32*1024)throw new IOException();out.write(b,0,n);}return out.toString("UTF-8").replace("__LANG__",L10n.language()).replace("__I18N__",L10n.mobile().toString().replace("<","\\u003c"));}}
}
